import { useState, useEffect } from "react";
import { API_URL } from "../config/api";
import { toast } from "react-hot-toast";
import { confirmarAccion } from "../utils/alerts";

export function usePeriodos() {
  const [periodos, setPeriodos] = useState([]);
  const [nuevoPeriodo, setNuevoPeriodo] = useState({
    mes: "",
    ano: new Date().getFullYear(),
    estado: "Abierto"
  });
  const [periodoCargado, setPeriodoCargado] = useState(false);

  useEffect(() => {
    const cargarPeriodos = async () => {
      try {
        const res = await fetch(`${API_URL}/periodo`);
        if (res.ok) {
          const data = await res.json();
          setPeriodos(data);
        }
      } catch (error) {
        console.error("Error cargando periodos:", error);
        toast.error("No se pudieron cargar los períodos");
      }
    };
    cargarPeriodos();
  }, []);

  const crearPeriodo = async (e) => {
    e.preventDefault();
    try {
      const res = await fetch(`${API_URL}/periodo/`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(nuevoPeriodo),
      });
      if (res.ok) {
        const data = await res.json();
        setPeriodos([...periodos, data]);
        limpiarFormularioPeriodo();
        toast.success("Período creado exitosamente");
      } else {
        toast.error("Error al crear el período. Verifique los datos.");
      }
    } catch (error) {
      console.error("Error al crear periodo:", error);
      toast.error("Error de conexión con el backend");
    }
  };

  const eliminarPeriodo = async (id) => {
    // Reemplazo del window.confirm nativo
    const confirmado = await confirmarAccion(
      "¿Seguro que deseas eliminar este período?",
      "Esta acción eliminará el registro del sistema."
    );

    if (!confirmado) return;

    try {
      const res = await fetch(`${API_URL}/periodo/${id}`, { method: "DELETE" });
      if (res.ok) {
        setPeriodos(periodos.filter(p => p.id !== id));
        toast.success("Período eliminado correctamente");
      } else {
        toast.error("No se puede eliminar, verifique si tiene planillas asociadas");
      }
    } catch (error) {
      console.error("Error al eliminar periodo:", error);
      toast.error("Error de conexión al intentar eliminar");
    }
  };

  const generarProximoPeriodo = async () => {
    try {
      const res = await fetch(`${API_URL}/periodo/generar_proximo/`, { method: "POST" });
      if (res.ok) {
        const data = await res.json();
        setPeriodos([...periodos, data]);
        toast.success("Próximo período generado automáticamente");
      } else {
        toast.error("Error al generar el próximo período");
      }
    } catch (error) {
      console.error("Error generando periodo:", error);
      toast.error("Error de conexión con el servidor");
    }
  };

  const cargarPeriodo = (p) => {
    setNuevoPeriodo({ mes: p.mes, ano: p.ano, estado: p.estado });
    setPeriodoCargado(true);
  };

  const limpiarFormularioPeriodo = () => {
    setNuevoPeriodo({ mes: "", ano: new Date().getFullYear(), estado: "Abierto" });
    setPeriodoCargado(false);
  };

  return {
    periodos,
    nuevoPeriodo,
    setNuevoPeriodo,
    periodoCargado,
    crearPeriodo,
    eliminarPeriodo,
    cargarPeriodo,
    limpiarFormularioPeriodo,
    generarProximoPeriodo
  };
}
